// useNotificationSounds (#3082, epic #3071 P4a) — the app dogfooding its own Sounds library. When the
// opt-in `soundNotifications` flag is ON (default OFF, Settings → Appearance), watch the coordination
// log and play a Signal-kit cue on each NEW completion/wait event since mount: landing/merge → success,
// failure → error, a worker pausing (`bsc-wait`) → notify. Mounted once app-wide (App.tsx).
//
// Baseline discipline: we never voice the backlog. On mount (and each time the flag is re-enabled) the
// first successful read just records the current line count; only lines appended AFTER that sound. A
// shrunk/replaced log re-baselines rather than replaying. While OFF the poll is a no-op (no I/O).
//
// THE MAPPING AND THE BASELINE RULE ARE BACKEND-SIDE (`logs::notify_cues`). This hook used to call
// `readCoordState()`, which folds the whole 1000-line window into coordination state — every waiter,
// latch, brief and request — and then used exactly two things from it: `lines.length` and a slice.
// At a 1 Hz cadence that fold was rebuilt and discarded once a second. `coord_notify_cues` parses
// only the NEW lines and returns the count plus the deduped cue ids; no log line crosses the boundary.
// What stays here is PLAYING them, which needs Web Audio.
import { useRef } from "react";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { playCue } from "@/features/sounds/lib/synth";
import { STARTER_KIT } from "@/features/sounds/lib/soundKits";

/** Poll cadence for the coord-log watch (ms). Matches the coordinator's own 1 Hz read. */
const POLL_MS = 1000;

/** One tick, as `coord_notify_cues` answers it: the new line count, and the cues for what is new. */
interface NotifyTick {
  total: number;
  /** Signal-kit cue ids (`src-tauri/data/sounds/signal.json`), deduped, in order. */
  cues: string[];
}

export function useNotificationSounds(): void {
  // Count of coord-log lines already accounted for; -1 = "not yet baselined" (re-baseline next read).
  const seen = useRef(-1);
  // Whether the flag was ON last tick — a false→true edge forces a re-baseline so enabling mid-session
  // starts from "now" instead of dumping the backlog.
  const wasOn = useRef(false);

  usePoll(async (isCancelled) => {
    const on = useAppStore.getState().soundNotifications;
    if (!on) { wasOn.current = false; return; }                     // OFF → no I/O
    if (!wasOn.current) { wasOn.current = true; seen.current = -1; } // just enabled → re-baseline

    // `null` on a read failure keeps the baseline and retries next tick — the same guard the old
    // `readCoordState` null gave us. A DEFAULTED tick (total 0) would silently re-baseline instead.
    const tick = await safeInvoke<NotifyTick | null>("coord_notify_cues", { seen: seen.current }, null);
    if (isCancelled() || !tick) return;

    // Baselining, a shrunk log and "nothing new" all come back with no cues, so this is one path.
    seen.current = tick.total;
    for (const id of tick.cues) {
      const cue = STARTER_KIT.cues.find((c) => c.id === id);
      if (cue) playCue(cue, STARTER_KIT);
    }
  }, POLL_MS);
}
